// 1. Input Validation & Initialization
if (!wo_input.enable || wo_input.wheels == NULL || wo_config.count != 4) {
    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.torque.command = (adcs_vec3_t){0, 0, 0};
    wo_output.torque.saturated_axes = 0U;
    wo_output.maximum_speed = 0.0;
    wo_output.predicted_maximum_speed = 0.0;
    wo_output.predicted_trip_mask = 0U;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    for(int i=0; i<4; ++i) {
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = 0.0;
    }
    return;
}

// Check configuration validity
if (wo_config.release_rad_s >= wo_config.warn_rad_s ||
    wo_config.warn_rad_s >= wo_config.trip_rad_s ||
    !isfinite(wo_config.dt_s) || wo_config.dt_s <= 0.0 ||
    !isfinite(wo_config.prediction_horizon_s) || wo_config.prediction_horizon_s < 0.0 ||
    !isfinite(wo_config.gain) || wo_config.gain < 0.0 ||
    !isfinite(wo_config.torque_limit) || wo_config.torque_limit <= 0.0 ||
    !isfinite(wo_config.torque_slew) || wo_config.torque_slew <= 0.0 ||
    wo_config.minimum_active_cycles < 1 || wo_config.minimum_active_cycles > 100 ||
    wo_config.release_cycles < 1 || wo_config.release_cycles > 100 ||
    wo_config.recovery_cycles < 1 || wo_config.recovery_cycles > 100) {
    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.torque.command = (adcs_vec3_t){0, 0, 0};
    wo_output.torque.saturated_axes = 0U;
    wo_output.maximum_speed = 0.0;
    wo_output.predicted_maximum_speed = 0.0;
    wo_output.predicted_trip_mask = 0U;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    for(int i=0; i<4; ++i) {
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = 0.0;
    }
    return;
}

// Calculate current momentum
adcs_status_t status = adcs_wheel_momentum(wo_input.wheels, wo_config.count, &wo_output.momentum);
if (status != ADCS_OK || !isfinite(wo_output.momentum.x) || !isfinite(wo_output.momentum.y) || !isfinite(wo_output.momentum.z)) {
    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.torque.command = (adcs_vec3_t){0, 0, 0};
    wo_output.torque.saturated_axes = 0U;
    wo_output.maximum_speed = 0.0;
    wo_output.predicted_maximum_speed = 0.0;
    wo_output.predicted_trip_mask = 0U;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    for(int i=0; i<4; ++i) {
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = 0.0;
    }
    return;
}
wo_output.momentum_norm = adcs_vec3_norm(&wo_output.momentum);

// Handle first run or enable toggle: reset history and state
if (!wo_state.history_initialized || !wo_input.enable) {
    for (int i = 0; i < 4; ++i) {
        wo_state.previous_speed_rad_s[i] = wo_input.wheels[i].speed_rad_s;
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = wo_input.wheels[i].speed_rad_s;
    }
    wo_state.history_initialized = 1;
    wo_state.elapsed = 0;
    wo_state.clean = 0;
    wo_state.recovery_count = 0;

    // Reset output state
    wo_output.maximum_speed = 0.0;
    wo_output.predicted_maximum_speed = 0.0;
    wo_output.predicted_trip_mask = 0U;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    wo_output.torque.command = (adcs_vec3_t){0, 0, 0};
    wo_output.torque.saturated_axes = 0U;

    // Determine initial mode based on prediction (with 0 acceleration)
    double pred_max = 0.0;
    unint32 trip_mask = 0U;
    for (int i = 0; i < 4; ++i) {
        double current_speed = wo_input.wheels[i].speed_rad_s;
        double predicted_speed = current_speed; 
        double abs_pred = fabs(predicted_speed);
        if (abs_pred > pred_max) pred_max = abs_pred;
        if (abs_pred >= wo_config.trip_rad_s) {
            trip_mask |= (1U << i);
        }
    }

    wo_output.maximum_speed = pred_max; // Current max is also used as initial since acc=0
    wo_output.predicted_maximum_speed = pred_max;
    wo_output.predicted_trip_mask = trip_mask;

    if (pred_max >= wo_config.trip_rad_s) {
        wo_state.mode = WO_ACTIVE;
    } else if (pred_max >= wo_config.warn_rad_s) {
        wo_state.mode = WO_WATCH;
    } else {
        wo_state.mode = WO_OFF;
    }
} else {
    // Normal operation: update state machine transitions

    // Calculate accelerations and predictions
    double dt = wo_config.dt_s;
    double horizon = wo_config.prediction_horizon_s;
    double max_abs_current = 0.0;
    double max_abs_predicted = 0.0;
    unint32 trip_mask = 0U;

    for (int i = 0; i < 4; ++i) {
        double current_speed = wo_input.wheels[i].speed_rad_s;
        double prev_speed = wo_state.previous_speed_rad_s[i];

        double accel = (current_speed - prev_speed) / dt;
        double predicted_speed = current_speed + accel * horizon;

        wo_output.acceleration_rad_s2[i] = accel;
        wo_output.predicted_speed_rad_s[i] = predicted_speed;

        double abs_current = fabs(current_speed);
        double abs_predicted = fabs(predicted_speed);

        if (abs_current > max_abs_current) max_abs_current = abs_current;
        if (abs_predicted > max_abs_predicted) max_abs_predicted = abs_predicted;

        if (abs_predicted >= wo_config.trip_rad_s) {
            trip_mask |= (1U << i);
        }

        // Update history for next cycle
        wo_state.previous_speed_rad_s[i] = current_speed;
    }

    wo_output.maximum_speed = max_abs_current;
    wo_output.predicted_maximum_speed = max_abs_predicted;
    wo_output.predicted_trip_mask = trip_mask;

    // State Machine Transitions
    if (wo_state.mode == WO_ACTIVE) {
        // Inside ACTIVE
        wo_state.elapsed++;

        // Check for release condition
        if (wo_state.elapsed >= wo_config.minimum_active_cycles) {
            if (max_abs_current <= wo_config.release_rad_s && max_abs_predicted <= wo_config.release_rad_s) {
                wo_state.clean++;
            } else {
                wo_state.clean = 0;
            }

            if (wo_state.clean >= wo_config.release_cycles) {
                wo_state.mode = WO_RECOVERY;
                wo_state.clean = 0;
                wo_state.recovery_count = 0;
            }
        }
    } else if (wo_state.mode == WO_RECOVERY) {
        // Inside RECOVERY
        // If predicted trip occurs, go back to ACTIVE
        if (trip_mask != 0U) {
            wo_state.mode = WO_ACTIVE;
            wo_state.elapsed = 0;
        } else {
            wo_state.recovery_count++;
            if (wo_state.recovery_count >= wo_config.recovery_cycles) {
                wo_state.mode = WO_OFF;
            }
        }
    } else if (wo_state.mode == WO_WATCH) {
        if (max_abs_predicted >= wo_config.trip_rad_s) {
            wo_state.mode = WO_ACTIVE;
            wo_state.elapsed = 0;
        } else if (max_abs_predicted < wo_config.warn_rad_s) {
            wo_state.mode = WO_OFF;
        }
    } else if (wo_state.mode == WO_OFF) {
        if (max_abs_predicted >= wo_config.warn_rad_s) {
            wo_state.mode = WO_WATCH;
        }
    }
}

wo_output.mode = wo_state.mode;

// Control Law Calculation
wo_output.torque.command = (adcs_vec3_t){0, 0, 0};
wo_output.torque.saturated_axes = 0U;
wo_output.saturation_mask = 0U;
wo_output.slew_mask = 0U;

if (wo_state.mode == WO_ACTIVE) {
    // Calculate desired torque: -gain * momentum
    adcs_vec3_t desired_torque = adcs_vec3_scale(&wo_output.momentum, -wo_config.gain);

    // Apply per-axis magnitude limits
    adcs_actuator_limit_t limit = {
        .min_value = -wo_config.torque_limit,
        .max_value = wo_config.torque_limit,
        .max_slew_per_s = wo_config.torque_slew
    };

    double vals[3] = {desired_torque.x, desired_torque.y, desired_torque.z};
    double limited_vals[3];

    for (int i = 0; i < 3; ++i) {
        adcs_status_t st = adcs_limit_scalar(vals[i], &limit, &limited_vals[i]);
        if (st != ADCS_OK) {
             limited_vals[i] = ADCS_CLAMP(vals[i], -wo_config.torque_limit, wo_config.torque_limit);
        }
        if (fabs(limited_vals[i]) >= wo_config.torque_limit) {
            wo_output.saturation_mask |= (1U << i);
        }
    }

    // Apply slew limit relative to previous torque command
    double slew_limit = wo_config.torque_slew * wo_config.dt_s;
    double slewed_vals[3];

    for (int i = 0; i < 3; ++i) {
        double prev_val = i == 0 ? wo_state.previous_torque.x : (i == 1 ? wo_state.previous_torque.y : wo_state.previous_torque.z);
        double curr_val = limited_vals[i];
        double diff = curr_val - prev_val;

        if (diff > slew_limit) {
            slewed_vals[i] = prev_val + slew_limit;
            wo_output.slew_mask |= (1U << i);
        } else if (diff < -slew_limit) {
            slewed_vals[i] = prev_val - slew_limit;
            wo_output.slew_mask |= (1U << i);
        } else {
            slewed_vals[i] = curr_val;
        }
    }

    wo_output.torque.command.x = slewed_vals[0];
    wo_output.torque.command.y = slewed_vals[1];
    wo_output.torque.command.z = slewed_vals[2];

    // Update previous torque for next cycle
    wo_state.previous_torque = wo_output.torque.command;
} else {
    // In other modes, target command is zero. Apply slew limit from previous torque to zero.
    double slew_limit = wo_config.torque_slew * wo_config.dt_s;

    for (int i = 0; i < 3; ++i) {
        double prev_val = i == 0 ? wo_state.previous_torque.x : (i == 1 ? wo_state.previous_torque.y : wo_state.previous_torque.z);
        double target_val = 0.0;
        double diff = target_val - prev_val;

        if (diff > slew_limit) {
            wo_output.torque.command.m[i] = prev_val + slew_limit;
            wo_output.slew_mask |= (1U << i);
        } else if (diff < -slew_limit) {
            wo_output.torque.command.m[i] = prev_val - slew_limit;
            wo_output.slew_mask |= (1U << i);
        } else {
            wo_output.torque.command.m[i] = 0.0;
        }
    }
    wo_state.previous_torque = wo_output.torque.command;
}

