    adcs_actuator_limit_t limit = {
        .min_value = -wo_config.torque_limit,
        .max_value = wo_config.torque_limit,
        .max_slew_per_s = wo_config.torque_slew
    };

    double vals[3] = {desired_torque.x, desired_torque.y, desired_torque.z};
    double limited_vals[3];

    for (int i = 0; i < 3; ++i) {
        adcs_status_t st = adcs_limit_scalar(vals[i], &limit, &limited_vals[i]);
        if (st != ADCS_OK) {
             limited_vals[i] = ADCS_CLAMP(vals[i], -wo_config.torque_limit, wo_config.torque_limit);
