    // Apply slew limit relative to previous torque command
    double slew_limit = wo_config.torque_slew * wo_config.dt_s;
    double slewed_vals[3];

    for (int i = 0; i < 3; ++i) {
        double prev_val = i == 0 ? wo_state.previous_torque.x : (i == 1 ? wo_state.previous_torque.y : wo_state.previous_torque.z);
        double curr_val = limited_vals[i];
        double diff = curr_val - prev_val;

        if (diff > slew_limit) {
            slewed_vals[i] = prev_val + slew_limit;
            wo_output.slew_mask |= (1U << i);
        } else if (diff < -slew_limit) {
            slewed_vals[i] = prev_val - slew_limit;
            wo_output.slew_mask |= (1U << i);
        } else {
            slewed_vals[i] = curr_val;
        }
    }

    wo_output.torque.command.x = slewed_vals[0];
    wo_output.torque.command.y = slewed_vals[1];
    wo_output.torque.command.z = slewed_vals[2];

