        else val = desired_torque.z;

        double limited_val = LimitDouble(val, &(const adcs_actuator_limit_t){-max_torque, max_torque, 0});
        if (axis == 0) mag_lim_cmd.x = limited_val;
        else if (axis == 1) mag_lim_cmd.y = limited_val;
        else mag_lim_cmd.z = limited_val;

