    // OFF, WATCH, FAULT: Zero output
    wo_output.torque.command = (adcs_vec3_t){0, 0, 0};
    if (wo_state.mode == WO_FAULT || wo_state.mode == WO_OFF || wo_state.mode == WO_WATCH) {
         wo_state.previous_torque = (adcs_vec3_t){0, 0, 0};
    }
}

wo_output.mode = wo_state.mode;

