         for(int k=0; k<4; ++k) {
             wo_output.acceleration_rad_s2[k] = 0.0;
             wo_output.predicted_speed_rad_s[k] = 0.0;
         }
         wo_output.momentum = (adcs_vec3_t){0};
         wo_output.torque = (adcs_vec3_t){0};
         wo_output.momentum_norm = 0.0;
         wo_output.predicted_trip_mask = 0;
         wo_output.saturation_mask = 0;
         wo_output.slew_mask = 0;
         return;
    }

    if (!wo_state.history_initialized) {
        wo_state.previous_speed_rad_s[i] = speed;
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = speed;
        wo_state.history_initialized = 1;
    } else {
        double prev_speed = wo_state.previous_speed_rad_s[i];
        double accel = (speed - prev_speed) / wo_config.dt_s;
        wo_output.acceleration_rad_s2[i] = accel;
        wo_output.predicted_speed_rad_s[i] = speed + accel * wo_config.prediction_horizon_s;
        wo_state.previous_speed_rad_s[i] = speed;
    }

    double abs_curr = fabs(speed);
    if (abs_curr > current_max_abs_speed) current_max_abs_speed = abs_curr;

    double abs_pred = fabs(wo_output.predicted_speed_rad_s[i]);
    if (abs_pred > predicted_max_abs_speed) predicted_max_abs_speed = abs_pred;

    if (abs_pred >= wo_config.trip_rad_s) {
        trip_mask |= (uint32_t)(1U << i);
    }
}

wo_output.maximum_speed = current_max_abs_speed;
wo_output.predicted_maximum_speed = predicted_max_abs_speed;
wo_output.predicted_trip_mask = trip_mask;
wo_output.saturation_mask = 0; 
wo_output.slew_mask = 0;       

// 4. State Machine Logic
wo_mode_t next_mode = wo_state.mode;
int entering_active = 0;
int entering_recovery = 0;
int is_trip_occurred = (trip_mask != 0);

switch (wo_state.mode) {
    case WO_OFF:
        if (predicted_max_abs_speed >= wo_config.warn_rad_s) {
            next_mode = WO_WATCH;
        }
        break;
    case WO_WATCH:
        if (predicted_max_abs_speed >= wo_config.trip_rad_s) {
            next_mode = WO_ACTIVE;
        } else if (predicted_max_abs_speed < wo_config.warn_rad_s) {
            next_mode = WO_OFF;
        }
        break;
    case WO_ACTIVE:
        wo_state.elapsed++;
        if (wo_state.elapsed >= wo_config.minimum_active_cycles) {
            int current_ok = (current_max_abs_speed <= wo_config.release_rad_s);
            int predicted_ok = (predicted_max_abs_speed <= wo_config.release_rad_s);

            if (current_ok && predicted_ok) {
                wo_state.clean++;
                if (wo_state.clean >= wo_config.release_cycles) {
                    next_mode = WO_RECOVERY;
                    entering_recovery = 1;
                }
            } else {
                wo_state.clean = 0;
            }
        }
        break;
    case WO_RECOVERY:
        if (is_trip_occurred) {
            next_mode = WO_ACTIVE;
            entering_active = 1;
        } else {
            wo_state.recovery_count++;
            if (wo_state.recovery_count >= wo_config.recovery_cycles) {
                next_mode = WO_OFF;
            }
        }
        break;
    default:
        next_mode = WO_FAULT;
        break;
}

// Handle transitions
if (next_mode == WO_ACTIVE && wo_state.mode != WO_ACTIVE) {
    wo_state.elapsed = 0;
    wo_state.clean = 0; 
    entering_active = 1;
}
if (next_mode == WO_RECOVERY && wo_state.mode != WO_RECOVERY) {
    wo_state.clean = 0;
    wo_state.recovery_count = 0;
    entering_recovery = 1;
}

wo_state.mode = next_mode;
wo_output.mode = wo_state.mode;
wo_output.clean = wo_state.clean;
wo_output.elapsed = wo_state.elapsed;
wo_output.recovery_count = wo_state.recovery_count;

// 5. Control Law Generation
adcs_vec3_t desired_torque = (adcs_vec3_t){0, 0, 0};

if (wo_state.mode == WO_ACTIVE) {
    desired_torque = adcs_vec3_scale(&wo_output.momentum, -wo_config.gain);
} else if (wo_state.mode == WO_RECOVERY) {
    desired_torque = (adcs_vec3_t){0, 0, 0};
} else {
    desired_torque = (adcs_vec3_t){0, 0, 0};
}

// Apply Magnitude Limit (Per-axis)
adcs_vec3_t limited_torque;
limited_torque.x = (desired_torque.x < -wo_config.torque_limit) ? -wo_config.torque_limit : 
                   ((desired_torque.x > wo_config.torque_limit) ? wo_config.torque_limit : desired_torque.x);
limited_torque.y = (desired_torque.y < -wo_config.torque_limit) ? -wo_config.torque_limit : 
                   ((desired_torque.y > wo_config.torque_limit) ? wo_config.torque_limit : desired_torque.y);
limited_torque.z = (desired_torque.z < -wo_config.torque_limit) ? -wo_config.torque_limit : 
                   ((desired_torque.z > wo_config.torque_limit) ? wo_config.torque_limit : desired_torque.z);

// Check saturation
if (limited_torque.x != desired_torque.x || limited_torque.y != desired_torque.y || limited_torque.z != desired_torque.z) {
    wo_output.saturation_mask = 0;
    if (limited_torque.x != desired_torque.x) wo_output.saturation_mask |= 1;
    if (limited_torque.y != desired_torque.y) wo_output.saturation_mask |= 2;
    if (limited_torque.z != desired_torque.z) wo_output.saturation_mask |= 4;
} else {
    wo_output.saturation_mask = 0;
}

// Apply Slew Limit
double max_delta = wo_config.torque_slew * wo_config.dt_s;
adcs_vec3_t delta = adcs_vec3_sub(&limited_torque, &wo_state.previous_torque);

int slew_sat_x = (delta.x > max_delta) || (delta.x < -max_delta);
int slew_sat_y = (delta.y > max_delta) || (delta.y < -max_delta);
int slew_sat_z = (delta.z > max_delta) || (delta.z < -max_delta);

adcs_vec3_t final_torque;
if (slew_sat_x || slew_sat_y || slew_sat_z) {
    wo_output.slew_mask = 0;
    if (slew_sat_x) {
        final_torque.x = wo_state.previous_torque.x + ((delta.x > 0) ? max_delta : -max_delta);
        wo_output.slew_mask |= 1;
    } else {
        final_torque.x = limited_torque.x;
    }
    if (slew_sat_y) {
        final_torque.y = wo_state.previous_torque.y + ((delta.y > 0) ? max_delta : -max_delta);
        wo_output.slew_mask |= 2;
    } else {
        final_torque.y = limited_torque.y;
    }
    if (slew_sat_z) {
        final_torque.z = wo_state.previous_torque.z + ((delta.z > 0) ? max_delta : -max_delta);
        wo_output.slew_mask |= 4;
    } else {
        final_torque.z = limited_torque.z;
    }
} else {
    final_torque = limited_torque;
    wo_output.slew_mask = 0;
}

// Update previous torque for next cycle
wo_state.previous_torque = final_torque;
wo_output.torque = final_torque;
